// PUBLIC endpoint: sin JWT. incident_id (UUID v4) = token (128 bits entropia).
const body = $input.first().json.body || {};
const incidentId = (body.incident_id || '').trim();
const decision = (body.decision || '').trim();
const comment = (body.comment || '').slice(0, 1000);
if (!incidentId || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(incidentId)) {
  return [{ json: { _error: 'INVALID_INCIDENT_ID', _status: 400, _details: 'incident_id debe ser UUID valido' } }];
}
if (!['approve','reject'].includes(decision)) {
  return [{ json: { _error: 'INVALID_DECISION', _status: 400, _details: "decision debe ser 'approve' o 'reject'" } }];
}
return [{ json: {
  incident_id: incidentId, decision, comment,
  request_id: 'req_' + Math.random().toString(36).slice(2, 10)
}}];

const r = $input.first()?.json;
const inp = $('Validate Input').first().json;
if (!r || !r.id) return [{ json: { _error: 'INCIDENT_NOT_FOUND', _status: 404, _details: 'token invalido o incident inexistente' } }];
if (r.status === 'approved' || r.status === 'rejected' || r.status === 'closed') {
  return [{ json: { _error: 'ALREADY_DECIDED', _status: 409, _details: 'Este imprevisto ya fue decidido (' + r.status + ')' } }];
}
if (r.status !== 'communicated') {
  return [{ json: { _error: 'NOT_COMMUNICATED', _status: 409, _details: 'El imprevisto aun no fue comunicado al cliente' } }];
}
let options = [];
try { options = typeof r.options === 'string' ? JSON.parse(r.options) : (r.options || []); } catch (e) {}
const selectedOpt = options[r.selected_option_index] || {};
return [{ json: {
  ...inp,
  tenant_id: r.tenant_id, project_id: r.project_id,
  project_name: r.project_name, client_name: r.client_name, client_email: r.client_email,
  selected_option: selectedOpt, selected_option_index: r.selected_option_index,
  cost_delta_eur: r.cost_delta_eur, time_delta_days: r.time_delta_days,
  description: r.description, location: r.location, severity: r.severity,
  new_status: inp.decision === 'approve' ? 'approved' : 'rejected'
}}];

